set-variable.value:
@{
    var text = (context.Request.Body == null ? "" : context.Request.Body.As<string>(preserveContent: true) ?? "").TrimStart();
    if (text.StartsWith("[")) { return "(batch)"; }
    try {
      var body = JObject.Parse(text);
      if ((string)body["method"] != "tools/call") { return ""; }
      var name = (string)body.SelectToken("params.name");
      return (name ?? "").Trim().ToLowerInvariant();
    } catch { return ""; }
  }

@{
    var tool = (string)context.Variables["mcp-tool"];
    if (tool.Length == 0) { return ""; }
    var vetted = "__VETTED_TOOLS__".Split(',');
    if (tool == "(batch)") { return "denied"; }
    if (!vetted.Contains(tool)) { return __DENY_UNLISTED__ ? "denied" : "unlisted"; }
    object errors;
    if (!context.Variables.TryGetValue("mcp-validation-errors", out errors) || errors == null) { return "passed"; }
    var list = JArray.Parse(JsonConvert.SerializeObject(errors));
    return list.Count == 0 ? "passed" : "rejected";
  }

@{
        var result = new JArray();
        if ((string)context.Variables["mcp-validation"] == "denied") {
          var batch = (string)context.Variables["mcp-tool"] == "(batch)";
          result.Add(new JObject(new JProperty("field", batch ? "request" : "name"), new JProperty("rule", batch ? "batch-not-allowed" : "tool-not-allowed")));
          return result.ToString(Newtonsoft.Json.Formatting.None);
        }
        var raw = JArray.Parse(JsonConvert.SerializeObject(context.Variables["mcp-validation-errors"]));
        var seen = new HashSet<string>();
        foreach (var e in raw) {
          var details = (e.Type == JTokenType.Object ? (string)e["Details"] : e.ToString()) ?? "";
          var message = details.IndexOf(" Message: ") >= 0 ? details.Substring(details.IndexOf(" Message: ")) : details;
          var rule = "invalid";
          if (message.Contains("Invalid type")) { rule = "type"; }
          else if (message.Contains("exceeds maximum value")) { rule = "maximum"; }
          else if (message.Contains("less than minimum value")) { rule = "minimum"; }
          else if (message.Contains("not defined in enum")) { rule = "enum"; }
          else if (message.Contains("Required properties are missing")) { rule = "required"; }
          else if (message.Contains("has not been defined")) { rule = "additionalProperties"; }
          else if (message.Contains("exceeds maximum length")) { rule = "maxLength"; }
          else if (message.Contains("less than minimum length")) { rule = "minLength"; }
          else if (message.Contains("does not match regex pattern")) { rule = "pattern"; }
          else if (message.Contains("does not match const")) { rule = "const"; }
          else if (message.Contains("exceeds maximum count")) { rule = "maxItems"; }
          else if (message.Contains("less than minimum count")) { rule = "minItems"; }
          var path = "";
          var pathAt = details.IndexOf("Path:");
          if (pathAt >= 0) {
            var rest = details.Substring(pathAt + 5);
            var space = rest.IndexOf(' ');
            path = space >= 0 ? rest.Substring(0, space) : rest;
          }
          var field = path.StartsWith("params.arguments.") ? path.Substring(17) : path;
          if (rule == "required") {
            var names = message.IndexOf("object: ");
            if (names >= 0) { field = message.Substring(names + 8).Split(new[] { ". Line:" }, StringSplitOptions.None)[0].TrimEnd('.').Trim(); }
          }
          if (field == "params.arguments" || field.Length == 0) { field = "arguments"; }
          if (field.Length > 64) { field = field.Substring(0, 64); }
          if (seen.Add(field + "|" + rule)) {
            result.Add(new JObject(new JProperty("field", field), new JProperty("rule", rule)));
          }
        }
        return result.ToString(Newtonsoft.Json.Formatting.None);
      }

return-response.set-body:
@{
          JToken id = JValue.CreateNull();
          try { id = context.Request.Body.As<JObject>(preserveContent: true)["id"] ?? JValue.CreateNull(); } catch { }
          var tool = (string)context.Variables["mcp-tool"];
          var violations = JArray.Parse((string)context.Variables["mcp-violations"]);
          var parts = violations.Select(v => (string)v["field"] + " violates " + (string)v["rule"]).ToArray();
          var denied = (string)context.Variables["mcp-validation"] == "denied";
          var text = denied
            ? (tool == "(batch)" ? "JSON-RPC batch requests are not supported by this gateway." : "Tool " + tool + " is not allowed by the gateway policy.")
            : "Invalid arguments for tool " + tool + ": " + string.Join("; ", parts) + ". Rejected by the API gateway before reaching the server.";
          var version = context.Request.Headers.GetValueOrDefault("MCP-Protocol-Version", "2025-06-18");
          var response = new JObject(new JProperty("jsonrpc", "2.0"), new JProperty("id", id));
          if (!denied && string.CompareOrdinal(version, "2025-11-25") >= 0) {
            response["result"] = new JObject(
              new JProperty("content", new JArray(new JObject(new JProperty("type", "text"), new JProperty("text", text)))),
              new JProperty("isError", true));
          } else {
            response["error"] = new JObject(
              new JProperty("code", -32602),
              new JProperty("message", text),
              new JProperty("data", new JObject(new JProperty("tool", tool), new JProperty("violations", violations), new JProperty("source", "api-gateway")__DEBUG_RAW__)));
          }
          return response.ToString(Newtonsoft.Json.Formatting.None);
        }
